  'd":0.4,"unit":"fraction"},{"stage":"monte_carlo","id":"p_value","label":"p-value of the mean-return test","operator":"<","threshold":0.05,"unit":"p_va',
  'lue"},{"stage":"paper_trading","id":"paper_retention","label":"Paper return retained from the backtest","operator":">=","threshold":0.7,"unit":"fracti',
  'on"},{"stage":"paper_trading","id":"paper_breaches","label":"Loss-limit breaches","operator":"<=","threshold":0.0,"unit":"count"}],"thresholds_source"',
  ':"BE Synopsis Sem VI, validation framework","basis":["Metrics use daily bars, annualised with 252 bars a year; the Sharpe ratio uses a 6.5% a year ris',
